const allReviews = $('Get All Reviews1').first().json.reviews;
const loggedRows = $('Get Previous Records1').all();
const loggedIds = loggedRows.map(r => r.json.review_id).filter(Boolean);

const unprocessed = allReviews.filter(r => {
  if (loggedIds.includes(r.review_id)) return false;

  const hasReviewId = r.review_id && r.review_id !== '';
  const hasImages = [];
  const hasTitle = r.place_info?.title && r.place_info.title !== '';
  const hasAddress = r.place_info?.address && r.place_info.address !== '';
  const hasDataId = r.place_info?.data_id && r.place_info.data_id !== '';

  return hasReviewId && hasImages && hasTitle && hasAddress && hasDataId;
});

return unprocessed.map(r => ({ json: r }));

const r = $('Pick Newest Unprocessed Reviews1').first().json;
// Extract city from address (last meaningful part before country)
const addressParts = (r.place_info.address || '').split(',');
const city = addressParts.length >= 2 ? addressParts[addressParts.length - 2].trim() : '';
const country = addressParts.length >= 1 ? addressParts[addressParts.length - 1].trim() : '';
return [{
  json: {
    review_id: r.review_id,
    restaurant: {
      name: r.place_info.title,
      address: r.place_info.address,
      city: city,
      country: country,
      type: r.place_info.type,
      data_id: r.place_info.data_id,
      coordinates: r.place_info.gps_coordinates,
      thumbnail: r.place_info.thumbnail
    },
    review: {
      rating: r.rating,
      date: r.date,
      text: r.snippet,
      text_translated: r.translated_snippet,
      likes: r.likes,
      details: r.details || {},
    },
    images: $input.all().slice(0, 7).map(item => ({ url: item.json.image }))
  }
}];

const data = $input.first().json;
const { images, meta, restaurant, review, ...rest } = data;
const { thumbnail, ...cleanRestaurant } = restaurant;
const { rating, date, text_translated, likes, details, owner_response, ...cleanReview } = review;
return [{
  json: {
    ...rest,
    restaurant: cleanRestaurant,
    review: cleanReview,
    food_images: images.slice(0, 4).map(img => img.url)
  }
}];

const merged = $input.first().json;

function sanitize(str) {
  if (!str) return '';
  return str
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')
    .replace(/[\u{1F300}-\u{1F9FF}]/gu, '')
    .replace(/[\u{2600}-\u{27BF}]/gu, '')
    .replace(/[\u{FE00}-\u{FEFF}]/gu, '')
    .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
    .replace(/\n/g, ' ').replace(/\r/g, '').replace(/\t/g, ' ')
    .trim();
}

return [{
  json: {
    restaurantName: sanitize(merged.restaurant?.name || 'el restaurante'),
    restaurantType: sanitize(merged.restaurant?.type || 'restaurante'),
    restaurantAddress: sanitize(merged.restaurant?.address || ''),
    restaurantCity: sanitize(merged.restaurant?.city || ''),
    restaurantCountry: sanitize(merged.restaurant?.country || ''),
    reviewText: sanitize(merged.review?.text || ''),
    foodImages: merged.food_images || [],
    insideImage: merged.inside_image_url || '',
    maleAvatarImage: merged.male_avatar_image || '',
    femaleAvatarImage: merged.female_avatar_image || '',
    review_id: merged.review_id
  }
}];

const response = $input.first().json;
const content = response.choices[0].message.content;

let scriptData;
try {
  scriptData = JSON.parse(content);
} catch(e) {
  scriptData = JSON.parse(content.replace(/```json|```/g, '').trim());
}

const d = $('Prepare Data for Script').first().json;

const foodImages = d.foodImages || [];
const insideImg  = d.insideImage || '';
const maleImg    = d.maleAvatarImage || '';
const femaleImg  = d.femaleAvatarImage || '';

// Build title in format: RESTAURANT NAME. // CITY COUNTRY
const titleDisplay = (d.restaurantName + '. // ' + d.restaurantCity + ' ' + d.restaurantCountry).toUpperCase().trim();

const masterPromptIntro = 'ULTRA REALISTIC CINEMATIC STYLE. Ultra realistic cinematic restaurant video. Premium movie look. Natural lighting. 24fps cinematic motion. Shallow depth of field. Real-world physics. CRITICAL: Use ONLY the real food photographs provided. NEVER invent dishes or generate fake food. Food must remain physically grounded, realistic, detailed. IMPORTANT: NEVER show eating or holding shells of mussels, clams, oysters, lemon rinds or any inedible food parts - only show edible food portions. Maintain identical avatars across all scenes - same face, hairstyle, age, body proportions, clothing. Hyperrealistic human motion: natural eye blinking (NO eye flickering or glitching), subtle breathing, micro-expressions, lip sync, photorealistic skin. NO fantasy visuals, NO AI glitches, NO face distortion, NO physics breaking. Everything must be grounded in real-world cinematic realism.';

const motion = 'Ultra-realistic human motion: natural stable eye blinking (absolutely NO eye flickering), subtle breathing, micro-expressions, lip sync, photorealistic skin, cinematic lighting. No robotic movement. No glitching.';

// SCENE 1 - Title overlay with restaurant name, city and location
const scene1Prompt = masterPromptIntro + ' SCENE 1 - RESTAURANT INTRO: Title card displayed prominently on screen: "' + titleDisplay + '". Cinematic slow pan across the beautiful interior of the restaurant. Soft warm lighting, aesthetic decor, bokeh background with guests dining. Male and Female character seated at a table, listening and smiling, gazing around admiringly. Natural, authentic, elegant. NO street address spoken. ' + motion + ' Vertical 9:16.';
const scene1Images = [
  ...(insideImg  ? [{ url: insideImg  }] : []),
  ...(maleImg    ? [{ url: maleImg    }] : []),
  ...(femaleImg  ? [{ url: femaleImg  }] : []),
  ...(foodImages[0] ? [{ url: foodImages[0] }] : [])
].slice(0, 4);

// SCENE 2A - Waiter serving
const scene2aPrompt = masterPromptIntro + ' SCENE 2A - WAITER SERVING: Professional waiter walks toward the table and places dishes elegantly. Real food from photos, show only edible portions. Male and Female characters look up with excitement. Close-up of hands setting down plates. Natural steam and realistic food detail. ' + motion + ' Vertical 9:16.';
const scene2aImages = [
  ...(insideImg  ? [{ url: insideImg  }] : []),
  ...(maleImg    ? [{ url: maleImg    }] : []),
  ...(femaleImg  ? [{ url: femaleImg  }] : []),
  ...(foodImages[1] ? [{ url: foodImages[1] }] : [])
].slice(0, 4);

// SCENE 2B - Food reveal
const scene2bPrompt = masterPromptIntro + ' SCENE 2B - HYPERREALISTIC FOOD REVEAL: Ultra cinematic food showcase using ONLY the real food photos provided. Show ONLY edible parts of food, never shells or inedible garnishes. Slow motion steam rising, floating spices macro lens, extreme close-up textures, sizzling plate fire sparks, golden sauce drizzle, final beauty shot of all dishes. Dark moody dramatic lighting. Multiple dishes shown. Smooth 360-degree camera rotation. No people. Vertical 9:16.';
const scene2bImages = foodImages.slice(0, 4).map(u => ({ url: u }));

// SCENE 3A - First bite reaction
const scene3aPrompt = masterPromptIntro + ' SCENE 3A - FIRST BITE REACTION: Male character takes first bite of real edible food (never shells or inedible parts) - eyes light up naturally, slow smile. Cut to Female character takes her bite - covers mouth in amazement, nods enthusiastically. Alternating close-up reaction shots. Warm cinematic lighting. Authentic emotional response. Stable natural eye blinking, absolutely NO eye flickering. ' + motion + ' Vertical 9:16.';
const scene3aImages = [
  ...(foodImages[0] ? [{ url: foodImages[0] }] : []),
  ...(foodImages[1] ? [{ url: foodImages[1] }] : []),
  ...(maleImg       ? [{ url: maleImg       }] : []),
  ...(femaleImg     ? [{ url: femaleImg     }] : [])
].slice(0, 4);

// SCENE 3B - Eating and talking
const scene3bPrompt = masterPromptIntro + ' SCENE 3B - SHARED CONVERSATION: Male and Female characters eating together naturally, laughing, talking, enjoying the real meal. Only edible food visible. Intercut with close-ups: fork lifting edible food from the real plates, juice glistening, hand picking glass. Candid warm documentary style. Stable natural eyes, NO flickering. ' + motion + ' Vertical 9:16.';
const scene3bImages = [
  ...(foodImages[2] ? [{ url: foodImages[2] }] : []),
  ...(foodImages[3] ? [{ url: foodImages[3] }] : []),
  ...(maleImg       ? [{ url: maleImg       }] : []),
  ...(femaleImg     ? [{ url: femaleImg     }] : [])
].slice(0, 4);

// SCENE 4 - Fast montage with Like/Follow CTA
const scene4Prompt = masterPromptIntro + ' SCENE 4 - FAST MONTAGE + CALL TO ACTION: High energy rapid-cut food montage showcasing ALL real photographed dishes (edible parts only). Quick cuts every 1.5 seconds. Vibrant saturated colors, dynamic camera angles. End scene: Male avatar looks directly at camera with stable eyes (NO flickering) and clearly says "Like". Then Female avatar looks directly at camera with stable eyes (NO flickering) and clearly says "Follow me". Warm smile, natural confident expression. Vertical 9:16.';
const scene4Images = [
  ...foodImages.slice(0, 2).map(u => ({ url: u })),
  ...(maleImg   ? [{ url: maleImg   }] : []),
  ...(femaleImg ? [{ url: femaleImg }] : [])
].slice(0, 4);

const endingVideoUrl = 'https://res.cloudinary.com/dffrucnde/video/upload/v1778667474/IMG_8823_utt70n.mp4';
const backgroundMusicUrl = 'https://res.cloudinary.com/dffrucnde/video/upload/v1778931747/AgusAlvarez_Luke_Bergs_-_The_Feeling_freetouse.com_wdotgq.mp3';

return [{
  json: {
    review_id: d.review_id,
    restaurantName: d.restaurantName,
    restaurantCity: d.restaurantCity,
    restaurantCountry: d.restaurantCountry,
    restaurantAddress: d.restaurantAddress,
    titleDisplay,
    hashtags: scriptData.hashtags || '',
    scene1Prompt,   scene1Images,
    scene2aPrompt,  scene2aImages,
    scene2bPrompt,  scene2bImages,
    scene3aPrompt,  scene3aImages,
    scene3bPrompt,  scene3bImages,
    scene4Prompt,   scene4Images,
    endingVideoUrl,
    backgroundMusicUrl
  }
}];

const d = $('Parse Script & Build Video Prompts').first().json;

const sc1  = $('Check Scene 1 Status').first().json.video.url;
const sc2a = $('Check Scene 2A Status').first().json.video.url;
const sc2b = $('Check Scene 2B Status').first().json.video.url;
const sc3a = $('Check Scene 3A Status').first().json.video.url;
const sc3b = $('Check Scene 3B Status').first().json.video.url;
const sc4  = $('Check Scene 4 Status').first().json.video.url;

const totalDuration = 60;

return [{
  json: {
    review_id: d.review_id,
    timeline: {
      tracks: [
        {
          clips: [
            { asset: { type: 'video', src: sc1  }, start: 0,  length: 8  },
            { asset: { type: 'video', src: sc2a }, start: 8,  length: 8  },
            { asset: { type: 'video', src: sc2b }, start: 16, length: 10 },
            { asset: { type: 'video', src: sc3a }, start: 26, length: 8  },
            { asset: { type: 'video', src: sc3b }, start: 34, length: 8  },
            { asset: { type: 'video', src: sc4  }, start: 42, length: 10 },
            { asset: { type: 'video', src: d.endingVideoUrl }, start: 52, length: 8 }
          ]
        },
        {
          clips: [
            {
              asset: {
                type: 'audio',
                src: d.backgroundMusicUrl,
                volume: 0.1,
                trim: 0
              },
              start: 0,
              length: totalDuration,
              transition: { in: 'fade', out: 'fade' }
            }
          ]
        }
      ]
    },
    output: { format: 'mp4', resolution: 'hd', aspectRatio: '9:16', fps: 30 }
  }
}];

const review_id = $('Parse Script & Build Video Prompts').first().json.review_id;
const final_video = $input.first().json.response.url;
return [{ json: { review_id, final_video } }];

const grokResponse = $input.first().json;
const insideImageUrl = grokResponse.choices[0].message.content.trim();

const name = $('Transform Payload to Structured Data1').first().json.restaurant.name;
const fullAddress = $('Transform Payload to Structured Data1').first().json.restaurant.address;
const addressParts = fullAddress.split(',');
const shortAddress = addressParts.slice(-2).map(s => s.trim()).join(', ');

return [{
  json: {
    inside_image_url: insideImageUrl,
    restaurant_name: name,
    short_address: shortAddress
  }
}];

const photos = $input.all().map(item => item.json);

const imageMessages = photos.map(p => ({
  type: "image_url",
  image_url: { url: p.original }
}));

const urlList = photos.map(p => p.original).join("\n");

return [{
  json: {
    requestBody: {
      model: "grok-4",
      messages: [
        {
          role: "system",
          content: `You are a strict restaurant interior photo selector.
TASK: Select the single best photo that shows the PHYSICAL INTERIOR SPACE of the restaurant.
MUST SHOW (at least one):
- Tables and chairs arranged in a dining room
- The restaurant's walls, ceiling, lighting fixtures, or decor
- The bar counter or dining hall
- The overall room/space ambiance
AUTOMATIC DISQUALIFICATION — reject any photo that primarily shows:
- Food or dishes (even if a table is visible in the background)
- A close-up of a pan, plate, or drink
- People eating without a clear view of the room
- Exterior of the building
- A menu or signage only
If NO qualifying interior photo exists, return the word: NONE
You MUST return ONLY one exact URL from the provided list. No explanation. No other text.`
        },
        {
          role: "user",
          content: [
            ...imageMessages,
            {
              type: "text",
              text: `Examine each image carefully. Reject any image where food, dishes, or a pan/plate is the main subject — even if the setting looks like a restaurant.
Available ORIGINAL URLs (pick BEST ONE interior photo):
${urlList}`
            }
          ]
        }
      ]
    }
  }
}];

const allItems = $input.all();

const httpsItems = allItems
  .filter(item => item.json.original?.startsWith('https'))
  .slice(0, 5);

return httpsItems;

const images = $input.first().json.images_results || [];

return images.map(img => ({
  json: {
    original: img.original
  }
}));

const name = $input.first().json.restaurant.name;
const fullAddress = $input.first().json.restaurant.address;
const addressParts = fullAddress.split(',');
const shortAddress = addressParts.slice(-2).map(s => s.trim()).join(', ').replace(/\b\d+\b/g, '').replace(/\s+/g, ' ').trim();

return [{
  json: {
    restaurant_name: name,
    short_address: shortAddress
  }
}];

const categories = $input.first().json.categories || [];

// Priority order: prefer actual food/drink photos, fall back to menu photos if that's all a place has
const priorityMatchers = [
  /^food\s*&?\s*drink$/i,   // exact "Food & drink"
  /^food$/i,
  /drink/i,
  /menu/i                   // last resort — these are photos of the menu itself, not dishes
];

let foodCategory = null;
for (const pattern of priorityMatchers) {
  foodCategory = categories.find(c => pattern.test(c.title));
  if (foodCategory) break;
}

return [{
  json: {
    ...$('Pick Newest Unprocessed Reviews1').first().json,
    category_id: foodCategory ? foodCategory.id : null,
    category_title: foodCategory ? foodCategory.title : null // handy for debugging/logging which category got picked
  }
}];

const photos = $input.first().json.photos || [];
const stillPhotos = photos.filter(p => !p.video);
return stillPhotos.map(p => ({
  json: {
    image: p.image.replace(/=w\d+-h\d+.*$/, '=w1600-h1200-k-no')
  }
}));
